function saveExamExtras(d,gid,pid,cid,rows,removalConfirmed=false){if(new Set(rows.map(r=>r.studentId)).size!==rows.length)throw Error('Alumno repetido en puntos extra.');const plans=rows.map(r=>examExtraPlan(d,gid,pid,cid,r)).filter(Boolean);if(plans.some(p=>p.remove)&&removalConfirmed!==true)throw Error('Confirma retirar las bonificaciones indicadas con 0.');if(plans.some(p=>Aula.index(d).exams.get(p.studentId+'|'+pid+'|'+cid)?.examStatus==='np'))throw Error('NP conserva cero: revierte NP antes de aplicar extras.');for(const p of plans)saveExamAdjustment(d,p.studentId,p.input);return plans.length}
