 const required=mode==='custom'?components.filter(c=>c.applicable).map(c=>c.key):mode==='mixed'?['theory','practice']:[mode],keys=new Set();let obtained=0,maximum=0,pending=false;
 for(const c of components){if(typeof validateExamSectionSnapshot==='function')validateExamSectionSnapshot(c);if(!c||!(mode==='custom'?typeof c.key==='string'&&c.key.trim()&&c.name?.trim()&&['theory','practice','other'].includes(c.type):['theory','practice'].includes(c.key))||keys.has(c.key)||typeof c.applicable!=='boolean')throw Error('Componente duplicado o inválido.');keys.add(c.key);if(c.applicable!==required.includes(c.key))throw Error('Componente no aplicable incompatible con el examen.');if(!c.applicable){if(c.obtained!==null||c.max!==null)throw Error('Un componente no aplicable no lleva puntos.');continue}if(!Number.isFinite(c.max)||c.max<=0)throw Error('Indica puntos máximos positivos.');maximum+=c.max;if(c.obtained===null)pending=true;else{if(!Number.isFinite(c.obtained)||c.obtained<0||c.obtained>c.max)throw Error('Los puntos obtenidos deben estar entre cero y el máximo.');obtained+=c.obtained}}
