function examMakeComponents(mode,theoryMax,practiceMax,theory,practice){return ['theory','practice'].map(key=>{const applicable=mode==='mixed'||mode===key,raw=key==='theory'?theory:practice;return {key,name:key==='theory'?'Teoría':'Práctica',applicable,max:applicable?Number(key==='theory'?theoryMax:practiceMax):null,obtained:applicable&&raw!==''&&raw!==null&&raw!==undefined?examPointNumber(raw):null}})}
